/// Computes the arithmetic series S(n) = 1 + 2 + ... + n using a simple loop.
/// 
/// # Arguments
///
/// * `n` – a non‐negative 64‐bit unsigned integer
///
/// # Returns
///
/// The exact sum 1 + 2 + … + n as a `u64`.
///
/// # Panics
///
/// This implementation does *not* explicitly check that S(n) < 10_000 at runtime,
/// but the caller is assumed to choose `n` small enough that the result fits
/// comfortably in a `u64` (and in particular is < 10_000 as per the problem statement).
pub fn compute_arith_sum(n: u64) -> u64 {
    let mut sum = 0;
    let mut i = 1;
    while i <= n {
        // At each step, `sum` holds 1 + 2 + … + (i − 1).
        sum += i;
        i += 1;
    }
    // Now sum == 1 + 2 + … + n
    sum
}

